1	import type { PaneAxis, PaneEdge, PaneNode } from "@nib-ui/ui-contracts";
2	import { MIN_DOCK_HEIGHT, MIN_DOCK_WIDTH } from "./docks";
3	
4	/** Index of a child, repeated per level: how a component addresses a split it renders. */
5	export type NodePath = number[];
6	
7	export function leafNode(instanceId: string): PaneNode {
8	  return { kind: "leaf", instanceId };
9	}
10	
11	export function axisOf(edge: PaneEdge): PaneAxis {
12	  return edge === "left" || edge === "right" ? "row" : "column";
13	}
14	
15	function leading(edge: PaneEdge): boolean {
16	  return edge === "left" || edge === "top";
17	}
18	
19	/** Fractions of the split's extent, one per child, summing to 1. */
20	export function normalizeSizes(sizes: readonly number[], count: number): number[] {
21	  if (count <= 0) return [];
22	  const share = 1 / count;
23	  const values = Array.from({ length: count }, (_, index) => {
24	    const value = sizes[index];
25	    return typeof value === "number" && Number.isFinite(value) && value > 0 ? value : share;
26	  });
27	  const total = values.reduce((sum, value) => sum + value, 0);
28	  return values.map((value) => value / total);
29	}
30	
31	/** A split of one child is that child: the tree never keeps a pointless level. */
32	function split(axis: PaneAxis, children: PaneNode[], sizes: readonly number[]): PaneNode {
33	  if (children.length === 1) return children[0]!;
34	  return { kind: "split", axis, children, sizes: normalizeSizes(sizes, children.length) };
35	}
36	
37	export function listLeaves(node: PaneNode): string[] {
38	  if (node.kind === "leaf") return [node.instanceId];
39	  return node.children.flatMap(listLeaves);
40	}
41	
42	export function hasLeaf(node: PaneNode, instanceId: string): boolean {
43	  return leafPath(node, instanceId) !== null;
44	}
45	
46	/** Where a leaf sits, as child indexes from the root; `[]` when it is the root. */
47	export function leafPath(node: PaneNode, instanceId: string): NodePath | null {
48	  if (node.kind === "leaf") return node.instanceId === instanceId ? [] : null;
49	  for (const [index, child] of node.children.entries()) {
50	    const path = leafPath(child, instanceId);
51	    if (path) return [index, ...path];
52	  }
53	  return null;
54	}
55	
56	export function nodeAt(node: PaneNode, path: NodePath): PaneNode | null {
57	  let current: PaneNode | undefined = node;
58	  for (const index of path) {
59	    if (!current || current.kind !== "split") return null;
60	    current = current.children[index];
61	  }
62	  return current ?? null;
63	}
64	
65	/** Adds a leaf against one edge of the whole tree — a drop on a frame's edge. */
66	export function insertAtEdge(root: PaneNode, instanceId: string, edge: PaneEdge): PaneNode {
67	  const axis = axisOf(edge);
68	  if (root.kind === "split" && root.axis === axis) {
69	    const share = 1 / (root.children.length + 1);
70	    const children = leading(edge)
71	      ? [leafNode(instanceId), ...root.children]
72	      : [...root.children, leafNode(instanceId)];
73	    const sizes = leading(edge) ? [share, ...root.sizes] : [...root.sizes, share];
74	    return split(axis, children, sizes);
75	  }
76	  const children = leading(edge) ? [leafNode(instanceId), root] : [root, leafNode(instanceId)];
77	  return split(axis, children, [0.5, 0.5]);
78	}
79	
80	/**
