85	export function insertBeside(
86	  root: PaneNode,
87	  instanceId: string,
88	  targetInstanceId: string,
89	  edge: PaneEdge,
90	): PaneNode {
91	  return insertInto(root, instanceId, targetInstanceId, edge) ?? root;
92	}
