100	  if (node.kind === "leaf") {
101	    return node.instanceId === targetInstanceId ? insertAtEdge(node, instanceId, edge) : null;
102	  }
103	
104	  const index = node.children.findIndex(
105	    (child) => child.kind === "leaf" && child.instanceId === targetInstanceId,
106	  );
107	  if (index >= 0 && node.axis === axisOf(edge)) {
108	    const half = (node.sizes[index] ?? 1 / node.children.length) / 2;
109	    const children = [...node.children];
110	    const sizes = [...node.sizes];
111	    children.splice(leading(edge) ? index : index + 1, 0, leafNode(instanceId));
112	    sizes.splice(index, 1, half, half);
113	    return split(node.axis, children, sizes);
114	  }
115	
116	  for (const [position, child] of node.children.entries()) {
117	    const replaced = insertInto(child, instanceId, targetInstanceId, edge);
118	    if (!replaced) continue;
119	    const children = [...node.children];
120	    children[position] = replaced;
121	    return split(node.axis, children, node.sizes);
122	  }
123	  return null;
124	}
