131	/** Drops every leaf the predicate rejects, collapsing the splits left behind. */
132	export function retainLeaves(
133	  node: PaneNode,
134	  keep: (instanceId: string) => boolean,
135	): PaneNode | null {
136	  if (node.kind === "leaf") return keep(node.instanceId) ? node : null;
137	
138	  const children: PaneNode[] = [];
139	  const sizes: number[] = [];
140	  let changed = false;
141	
142	  for (const [index, child] of node.children.entries()) {
143	    const next = retainLeaves(child, keep);
144	    if (next !== child) changed = true;
145	    if (!next) continue;
146	    children.push(next);
147	    sizes.push(node.sizes[index] ?? 0);
148	  }
149	
150	  if (!changed) return node;
151	  if (children.length === 0) return null;
152	  return split(node.axis, children, sizes);
