183	  sizes: readonly number[],
184	  index: number,
185	  delta: number,
186	  minimum = 0,
187	): number[] {
188	  const values = normalizeSizes(sizes, sizes.length);
189	  const before = values[index];
190	  const after = values[index + 1];
191	  if (before === undefined || after === undefined) return values;
192	
193	  const total = before + after;
194	  const floor = Math.min(Math.max(minimum, 0), total / 2);
