247	  const layout: TreeLayout = { leaves: [], splitters: [] };
248	  const none: Record<PaneEdge, boolean> = { left: false, right: false, top: false, bottom: false };
249	  place(root, { x: 0, y: 0, width: 1, height: 1 }, none, [], layout);
250	  return layout;
251	}
