253	function place(
254	  node: PaneNode,
255	  box: Box,
256	  gutters: Record<PaneEdge, boolean>,
257	  path: NodePath,
258	  layout: TreeLayout,
259	): void {
260	  if (node.kind === "leaf") {
261	    layout.leaves.push({ instanceId: node.instanceId, box, gutters });
262	    return;
263	  }
