265	  const row = node.axis === "row";
266	  const sizes = normalizeSizes(node.sizes, node.children.length);
267	  const extent = row ? box.width : box.height;
268	  const last = node.children.length - 1;
269	  let offset = row ? box.x : box.y;
270	
271	  for (const [index, child] of node.children.entries()) {
272	    const size = sizes[index];
273	    if (size === undefined) continue;
274	    const share = extent * size;
275	    const childBox = row
276	      ? { x: offset, y: box.y, width: share, height: box.height }
277	      : { x: box.x, y: offset, width: box.width, height: share };
278	    const childGutters = row
279	      ? { ...gutters, left: gutters.left || index > 0, right: gutters.right || index < last }
280	      : { ...gutters, top: gutters.top || index > 0, bottom: gutters.bottom || index < last };
281	    place(child, childBox, childGutters, [...path, index], layout);
282	    offset += share;
283	
284	    if (index === last) continue;
285	    layout.splitters.push({
286	      key: `${path.join(".")}/${index}`,
287	      path,
288	      index,
289	      axis: node.axis,
290	      extent,
291	      box: row
292	        ? { x: offset, y: box.y, width: 0, height: box.height }
293	        : { x: box.x, y: offset, width: box.width, height: 0 },
294	    });
295	  }
296	}
