298	export function pointInBox(box: Box, x: number, y: number): boolean {
299	  return x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height;
300	}
301	
302	/**
303	 * Which edge a pointer over a pane would attach to. The pane is cut into four
304	 * triangles about its centre, so exactly one edge is ever the answer.
305	 */
306	export function dropEdge(box: Box, x: number, y: number): PaneEdge {
307	  const horizontal = box.width > 0 ? (x - (box.x + box.width / 2)) / box.width : 0;
308	  const vertical = box.height > 0 ? (y - (box.y + box.height / 2)) / box.height : 0;
309	  if (Math.abs(horizontal) >= Math.abs(vertical)) return horizontal >= 0 ? "right" : "left";
310	  return vertical >= 0 ? "bottom" : "top";
311	}
